using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.API.Data; using RaceDay.API.DTOs; using RaceDay.API.Models;
namespace RaceDay.API.Controllers;
[ApiController,Route("api/events")]
public class EventsController(RaceDayContext db):ControllerBase
{
 /// <summary>Lists RaceDay events for public browsing.</summary>
 [HttpGet,ProducesResponseType(StatusCodes.Status200OK)] public async Task<IActionResult> List()=>Ok(await db.Events.AsNoTracking().OrderBy(x=>x.EventDate).Select(x=>new{x.EventId,x.OrganiserId,x.Title,x.Description,x.Location,x.EventDate,x.EventType,x.Status,x.BannerImageUrl,x.CreatedAt}).ToListAsync());
 /// <summary>Returns one event and its categories, or 404 if it does not exist.</summary>
 [HttpGet("{id:int}"),ProducesResponseType(StatusCodes.Status200OK),ProducesResponseType(StatusCodes.Status404NotFound)] public async Task<IActionResult> Get(int id){var e=await db.Events.AsNoTracking().Include(x=>x.Categories).Where(x=>x.EventId==id).Select(x=>new{x.EventId,x.OrganiserId,x.Title,x.Description,x.Location,x.EventDate,x.EventType,x.Status,x.BannerImageUrl,categories=x.Categories.Select(c=>new{c.CategoryId,c.Name,c.DistanceKm,c.MaxParticipants,c.EntryFee})}).FirstOrDefaultAsync();return e is null?NotFound():Ok(e);}
 /// <summary>Creates an event owned by the authenticated Organiser.</summary>
 [Authorize(Roles="Organiser"),HttpPost,ProducesResponseType(StatusCodes.Status201Created),ProducesResponseType(StatusCodes.Status403Forbidden)] public async Task<IActionResult> Create(EventRequest request){if(!ValidType(request.EventType))return BadRequest(new{message="EventType must be Run, Walk or Cycle."});if(!ValidStatus(request.Status))return BadRequest(new{message="Invalid event status."});var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var e=new Event{OrganiserId=id,Title=request.Title.Trim(),Description=request.Description,Location=request.Location.Trim(),EventDate=request.EventDate,EventType=request.EventType,Status=request.Status};db.Events.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=e.EventId},e);}
 /// <summary>Updates an event owned by the authenticated Organiser.</summary>
 [Authorize(Roles="Organiser"),HttpPut("{id:int}"),ProducesResponseType(StatusCodes.Status200OK),ProducesResponseType(StatusCodes.Status403Forbidden),ProducesResponseType(StatusCodes.Status404NotFound)] public async Task<IActionResult> Update(int id,EventRequest request){var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(!Owns(e))return Forbid();if(!ValidType(request.EventType)||!ValidStatus(request.Status))return BadRequest(new{message="Invalid event type or status."});e.Title=request.Title.Trim();e.Description=request.Description;e.Location=request.Location.Trim();e.EventDate=request.EventDate;e.EventType=request.EventType;e.Status=request.Status;await db.SaveChangesAsync();return Ok(e);}
 /// <summary>Cancels an event owned by the authenticated Organiser.</summary>
 [Authorize(Roles="Organiser"),HttpDelete("{id:int}"),ProducesResponseType(StatusCodes.Status204NoContent),ProducesResponseType(StatusCodes.Status403Forbidden),ProducesResponseType(StatusCodes.Status404NotFound)] public async Task<IActionResult> Delete(int id){var e=await db.Events.FindAsync(id);if(e is null)return NotFound();if(!Owns(e))return Forbid();e.Status="Cancelled";await db.SaveChangesAsync();return NoContent();}
 /// <summary>Lists the categories configured for an event.</summary>
 [HttpGet("{eventId:int}/categories"),ProducesResponseType(StatusCodes.Status200OK)] public async Task<IActionResult> Categories(int eventId){if(!await db.Events.AnyAsync(x=>x.EventId==eventId))return NotFound();return Ok(await db.Categories.AsNoTracking().Where(x=>x.EventId==eventId).Select(x=>new{x.CategoryId,x.EventId,x.Name,x.DistanceKm,x.MaxParticipants,x.EntryFee}).ToListAsync());}
 /// <summary>Adds a category to an event owned by the authenticated Organiser.</summary>
 [Authorize(Roles="Organiser"),HttpPost("{eventId:int}/categories"),ProducesResponseType(StatusCodes.Status201Created),ProducesResponseType(StatusCodes.Status403Forbidden)] public async Task<IActionResult> AddCategory(int eventId,CategoryRequest request){var e=await db.Events.FindAsync(eventId);if(e is null)return NotFound();if(!Owns(e))return Forbid();if(request.DistanceKm<=0||request.EntryFee<0||request.MaxParticipants<=0&&request.MaxParticipants is not null)return BadRequest(new{message="Distance must be positive, fee non-negative and capacity positive."});var c=new Category{EventId=eventId,Name=request.Name.Trim(),DistanceKm=request.DistanceKm,MaxParticipants=request.MaxParticipants,EntryFee=request.EntryFee};db.Categories.Add(c);await db.SaveChangesAsync();return Created($"/api/events/{eventId}/categories",c);}
 private bool Owns(Event e)=>e.OrganiserId==int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!); private static bool ValidType(string t)=>new[]{"Run","Walk","Cycle"}.Contains(t,StringComparer.OrdinalIgnoreCase); private static bool ValidStatus(string s)=>new[]{"Draft","Published","Completed","Cancelled"}.Contains(s,StringComparer.OrdinalIgnoreCase);
}